public class Student
{
    public string Name { get; set; }
    public List<string> Courses { get; set; }
}

List<Student> students = new List<Student>
{
    new Student { Name = "John", Courses = new List<string> { "Math", "Science" } },
    new Student { Name = "Jane", Courses = new List<string> { "English", "History" } }
};

// SelectMany flattens the nested collections
var allCourses = students.SelectMany(s => s.Courses);

// Result: "Math", "Science", "English", "History"

// SelectMany with student and course
var studentCourses = students.SelectMany(
    s => s.Courses,
    (student, course) => new { student.Name, course }
);

// Result:
// { Name = John, course = Math }
// { Name = John, course = Science }
// { Name = Jane, course = English }
// { Name = Jane, course = History }
